const ANCIENT_QUALITY_CHOICES = [
  { quality_id: 'ancient_legendary_gold', quality_name: '上古传说', quality_rank: 3.5, max_enhancement_level: 12, has_special_roll_rule: 1, notes: '上古前缀；强化上限与主词条上限沿用传说品质。' },
  { quality_id: 'ancient_mythic_red', quality_name: '上古神话', quality_rank: 4.5, max_enhancement_level: 16, has_special_roll_rule: 1, notes: '上古前缀；强化上限与主词条上限沿用神话品质。' },
]
const BASE_QUALITY_IDS = new Set(['rare_blue', 'epic_purple', 'legendary_gold', 'mythic_red'])
const setsOnly = ref(localStorage.getItem('eaia-sets-only') === '1')
watch(setsOnly, value => localStorage.setItem('eaia-sets-only', value ? '1' : '0'))

function normalizedEquipmentPayload(payload) {
  const root = { ...payload }, wrapped = root.values && typeof root.values === 'object'
  const values = { ...(wrapped ? root.values : root) }
  if (values.quality_id === 'ancient_legendary_gold') { values.quality_id = 'legendary_gold'; values.is_ancient = true }
  else if (values.quality_id === 'ancient_mythic_red') { values.quality_id = 'mythic_red'; values.is_ancient = true }
  else if (BASE_QUALITY_IDS.has(values.quality_id)) values.is_ancient = false
  if (Array.isArray(values.stats)) values.stats = values.stats.map((stat, index) => ({ ...stat, stat_type: stat?.stat_type ? String(stat.stat_type).toUpperCase() : stat?.stat_type, is_unlocked: index === 0 || (stat?.stat_value !== null && stat?.stat_value !== undefined && stat?.stat_value !== '') }))
  if (wrapped) { root.values = values; return root }
  return values
}
function augmentedCatalog(data) {
  const result = { ...data, gear_qualities: [...(data.gear_qualities || [])] }
  for (const quality of ANCIENT_QUALITY_CHOICES) if (!result.gear_qualities.some(row => row.quality_id === quality.quality_id)) result.gear_qualities.push(quality)
  result.stat_definitions = (data.stat_definitions || []).map(row => ({ ...row, stat_type: row.stat_type ? String(row.stat_type).toUpperCase() : row.stat_type }))
  return result
}
function replacedJsonResponse(response, payload) {
  const headers = new Headers(response.headers)
  headers.set('Content-Type', 'application/json; charset=utf-8')
  headers.delete('Content-Length')
  return new Response(JSON.stringify(payload), { status: response.status, statusText: response.statusText, headers })
}
const nativeFetch = window.fetch.bind(window)
const enhancedFetch = async (input, init = {}) => {
  const url = typeof input === 'string' ? input : input?.url || ''
  const method = String(init?.method || 'GET').toUpperCase()
  const hasBody = init?.body && typeof init.body === 'string'
  if (url.includes('/api/manage/equipment') && ['POST', 'PATCH'].includes(method) && hasBody) {
    try { init = { ...init, body: JSON.stringify(normalizedEquipmentPayload(JSON.parse(init.body))) } } catch { /* preserve non-JSON requests */ }
  }
  if (setsOnly.value && url.includes('/api/hero-core/recommend') && hasBody) {
    try { const payload = JSON.parse(init.body); if (!payload.team && !payload.hero_core_ids) init = { ...init, body: JSON.stringify({ ...payload, sets_only: true }) } } catch { /* preserve non-JSON requests */ }
  }
  const response = await nativeFetch(input, init)
  if (response.ok && url.includes('/api/catalog')) {
    try { return replacedJsonResponse(response, augmentedCatalog(await response.clone().json())) } catch { /* preserve response */ }
  }
  return response
}
window.fetch = enhancedFetch

