const catalog=ref({}),equipment=ref([]),equipmentSort=ref({key:'_seq',direction:'asc'}),equipmentPage=ref(1),equipmentSearchScope=ref('all'),equipmentEditor=ref({open:false,mode:'create',original:null,seq:null,form:null})
const cat=k=>catalog.value?.[k]||[],slotOptions=computed(()=>cat('equipment_slots')),setOptions=computed(()=>cat('sets').filter(x=>x.active!==0)),qualityOptions=computed(()=>cat('gear_qualities')),statOptions=computed(()=>cat('stat_definitions').filter(x=>x.active!==0)),rollOptions=computed(()=>cat('stat_roll_grades'))
function mainStat(r){return r.stats?.find(x=>Number(x.stat_index)===0||x.stat_source==='main')||null}function subStats(r){const m=mainStat(r);return(r.stats||[]).filter(x=>x!==m).sort((a,b)=>Number(a.stat_index)-Number(b.stat_index))}
function slotName(r){return pair(SLOT,r.slot_id,r.slot_name)}function qualityName(r){return pair(QUALITY,r.quality_id,r.quality_name)}
