const selectedHeroes=ref([]),addHero=ref(''),teamMode=ref('total'),teamTargetDef=ref(0),teamEnemies=ref(1),teamTrials=ref(16),teamCandidates=ref(5),teamCandidatePool=ref(24),teamJob=ref(null),teamResult=ref(null),teamError=ref('')
let teamTimer=null
