function heroStats(h){const b=h?.base_stats||{},r=h?.resources?.rage||{};return [[zh.value?'基础攻击':'Base ATK',b.atk],[zh.value?'基础生命':'Base HP',b.hp],[zh.value?'基础防御':'Base DEF',b.def],[zh.value?'基础暴击率':'Base CRIT',b.crit_rate,'pct'],[zh.value?'基础暴伤':'Base CRIT DMG',b.crit_dmg,'pct'],[zh.value?'基础攻速':'Base ATK SPD',b.atk_speed],[zh.value?'攻击间隔':'Attack Interval',b.attack_interval,'sec'],[zh.value?'初始 / 上限怒气':'Initial / Max Rage',r.initial!=null||r.max!=null?`${n(r.initial,0)} / ${n(r.max,0)}`:null]]}
